CREATE OR REPLACE FUNCTION public.apply_catalog_integrity_summary_delta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_organization_id uuid;
  v_projected_delta integer := 0;
  v_clear_delta integer := 0;
  v_incomplete_delta integer := 0;
  v_conflict_delta integer := 0;
  v_pending_delta integer := 0;
  v_failed_delta integer := 0;
  v_last_evaluated_at timestamptz;
begin
  v_organization_id := coalesce(new.organization_id, old.organization_id);
  perform public.ensure_catalog_integrity_summary(v_organization_id);

  if tg_op = 'INSERT' then
    v_projected_delta := 1;
    v_last_evaluated_at := new.last_evaluated_at;
    v_clear_delta := case when new.status = 'clear' then 1 else 0 end;
    v_incomplete_delta := case when new.status = 'incomplete' then 1 else 0 end;
    v_conflict_delta := case when new.status = 'conflict' then 1 else 0 end;
    v_pending_delta := case when new.status in ('unknown', 'queued', 'evaluating') then 1 else 0 end;
    v_failed_delta := case when new.status = 'failed' then 1 else 0 end;
  elsif tg_op = 'UPDATE' then
    v_last_evaluated_at := new.last_evaluated_at;
    if old.status is distinct from new.status then
      v_clear_delta := case when new.status = 'clear' then 1 else 0 end - case when old.status = 'clear' then 1 else 0 end;
      v_incomplete_delta := case when new.status = 'incomplete' then 1 else 0 end - case when old.status = 'incomplete' then 1 else 0 end;
      v_conflict_delta := case when new.status = 'conflict' then 1 else 0 end - case when old.status = 'conflict' then 1 else 0 end;
      v_pending_delta := case when new.status in ('unknown', 'queued', 'evaluating') then 1 else 0 end - case when old.status in ('unknown', 'queued', 'evaluating') then 1 else 0 end;
      v_failed_delta := case when new.status = 'failed' then 1 else 0 end - case when old.status = 'failed' then 1 else 0 end;
    end if;
  elsif tg_op = 'DELETE' then
    v_projected_delta := -1;
    v_clear_delta := case when old.status = 'clear' then -1 else 0 end;
    v_incomplete_delta := case when old.status = 'incomplete' then -1 else 0 end;
    v_conflict_delta := case when old.status = 'conflict' then -1 else 0 end;
    v_pending_delta := case when old.status in ('unknown', 'queued', 'evaluating') then -1 else 0 end;
    v_failed_delta := case when old.status = 'failed' then -1 else 0 end;
  end if;

  update public.catalog_integrity_summary
  set projected_products = greatest(0, projected_products + v_projected_delta),
      clear_count = greatest(0, clear_count + v_clear_delta),
      incomplete_count = greatest(0, incomplete_count + v_incomplete_delta),
      conflict_count = greatest(0, conflict_count + v_conflict_delta),
      pending_count = greatest(0, pending_count + v_pending_delta),
      failed_count = greatest(0, failed_count + v_failed_delta),
      last_evaluated_at = case
        when v_last_evaluated_at is null then last_evaluated_at
        else greatest(coalesce(last_evaluated_at, v_last_evaluated_at), v_last_evaluated_at)
      end,
      updated_at = now()
  where organization_id = v_organization_id;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_catalog_import(input_scope jsonb DEFAULT '{}'::jsonb, input_mode text DEFAULT 'upsert'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_mode text := lower(nullif(trim(coalesce(input_mode, '')), ''));
  v_scope jsonb := coalesce(input_scope, '{}'::jsonb);
  v_run_id uuid;
begin
  v_org_id := public.current_profile_org_id();

  if v_org_id is null or (public.current_profile_role() <> 'admin' and not public.is_superadmin()) then
    raise exception 'Only active admin users can import catalog data';
  end if;

  if v_mode is null then
    v_mode := 'upsert';
  end if;

  if v_mode = 'insert' then
    v_mode := 'insert_only';
  end if;

  if v_mode not in ('insert_only', 'upsert') then
    raise exception 'Catalog import mode must be insert_only or upsert';
  end if;

  if jsonb_typeof(v_scope) is distinct from 'object' then
    raise exception 'Catalog import scope must be a JSON object';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_org_id::text || ':catalog_import', 0)
  );

  if exists (
    select 1
    from public.catalog_import_runs r
    where r.organization_id = v_org_id
      and r.status in ('running', 'validating', 'validated', 'finalizing')
  ) then
    raise exception 'Another catalog import is already running.';
  end if;

  insert into public.catalog_import_runs (
    organization_id,
    mode,
    status,
    input_scope
  )
  values (
    v_org_id,
    v_mode,
    'running',
    v_scope
  )
  returning id into v_run_id;

  return jsonb_build_object(
    'status', 'running',
    'run_id', v_run_id,
    'organization_id', v_org_id,
    'mode', v_mode,
    'input_scope', v_scope
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_supplier_price_import(input_supplier_name text, input_brand text, input_mode text DEFAULT 'replace'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.current_profile_org_id() is null
     or (public.current_profile_role() <> 'admin' and not public.is_superadmin()) then
    raise exception 'Only active admin users can import supplier prices';
  end if;

  perform public.close_stale_supplier_price_import_runs(interval '2 hours');
  return public.begin_supplier_price_import_inner(input_supplier_name, input_brand, input_mode);
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_supplier_price_import_inner(input_supplier_name text, input_brand text, input_mode text DEFAULT 'replace'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_supplier_name text := nullif(trim(coalesce(input_supplier_name, '')), '');
  v_brand_name text := nullif(trim(coalesce(input_brand, '')), '');
  v_mode text := lower(nullif(trim(coalesce(input_mode, '')), ''));
  v_supplier_id uuid;
  v_brand_id uuid;
  v_run_id uuid;
begin
  v_org_id := public.current_profile_org_id();

  if v_org_id is null or not public.is_superadmin() then
    raise exception 'Only active superadmin users can import supplier prices';
  end if;

  if v_supplier_name is null then
    raise exception 'Supplier is required';
  end if;

  if v_brand_name is null then
    raise exception 'Brand is required';
  end if;

  if v_mode not in ('replace', 'merge') then
    raise exception 'Import mode must be replace or merge';
  end if;

  insert into public.suppliers (organization_id, name)
  values (v_org_id, v_supplier_name)
  on conflict (organization_id, normalized_name) do nothing;

  select s.id
  into v_supplier_id
  from public.suppliers s
  where s.organization_id = v_org_id
    and s.normalized_name = public.normalize_part_code(v_supplier_name)
  limit 1;

  insert into public.brands (organization_id, name)
  values (v_org_id, coalesce(v_brand_name, 'Unbranded'))
  on conflict (organization_id, normalized_name) do nothing;

  select b.id
  into v_brand_id
  from public.brands b
  where b.organization_id = v_org_id
    and b.normalized_name = public.normalize_part_code(coalesce(v_brand_name, 'Unbranded'))
  limit 1;

  if v_supplier_id is null or v_brand_id is null then
    raise exception 'Supplier or brand could not be resolved';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_org_id::text || ':' || v_supplier_id::text || ':' || v_brand_id::text, 0)
  );

  if exists (
    select 1
    from public.supplier_price_import_runs r
    where r.organization_id = v_org_id
      and r.supplier_id = v_supplier_id
      and r.brand_id = v_brand_id
      and r.status in ('running', 'finalizing')
  ) then
    raise exception 'Another import is already running for this supplier and brand.';
  end if;

  insert into public.supplier_price_import_runs (
    organization_id,
    supplier_id,
    brand_id,
    mode,
    status
  )
  values (
    v_org_id,
    v_supplier_id,
    v_brand_id,
    v_mode,
    'running'
  )
  returning id into v_run_id;

  return jsonb_build_object(
    'status', 'running',
    'run_id', v_run_id,
    'organization_id', v_org_id,
    'supplier_id', v_supplier_id,
    'brand_id', v_brand_id,
    'mode', v_mode
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.bulk_import_supplier_prices(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  result jsonb;
  org_id uuid := public.current_profile_org_id();
begin
  if org_id is null
     or (public.current_profile_role() <> 'admin' and not public.is_superadmin()) then
    raise exception 'Only active admin users can import supplier prices';
  end if;

  result := public.bulk_import_supplier_prices_inner(payload);

  update public.supplier_prices price
  set order_multiple = nullif(rows.order_multiple, 0)
  from (
    select distinct on (
      public.normalize_part_code(supplier_name),
      public.normalize_part_code(coalesce(brand, 'Unbranded')),
      public.normalize_part_code(product_code),
      coalesce(valid_from, current_date)
    ) supplier_name, brand, product_code, valid_from, order_multiple
    from jsonb_to_recordset(payload) as input_rows(
      supplier_name text,
      brand text,
      product_code text,
      valid_from date,
      order_multiple integer
    )
    where order_multiple is not null
    order by
      public.normalize_part_code(supplier_name),
      public.normalize_part_code(coalesce(brand, 'Unbranded')),
      public.normalize_part_code(product_code),
      coalesce(valid_from, current_date),
      order_multiple desc nulls last
  ) rows
  join public.suppliers supplier
    on supplier.organization_id = org_id
   and supplier.normalized_name = public.normalize_part_code(rows.supplier_name)
  join public.brands brand
    on brand.organization_id = org_id
   and brand.normalized_name = public.normalize_part_code(coalesce(rows.brand, 'Unbranded'))
  where price.organization_id = org_id
    and price.supplier_id = supplier.id
    and price.brand_id = brand.id
    and price.normalized_code = public.normalize_part_code(rows.product_code)
    and price.valid_from = coalesce(rows.valid_from, current_date)
    and rows.order_multiple is not null;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.catalog_products_market_segment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.market_segment := public.normalize_catalog_market_segment(new.market_segment);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_catalog_import(run_id uuid, message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_run_id uuid;
begin
  v_org_id := public.current_profile_org_id();

  if v_org_id is null or (public.current_profile_role() <> 'admin' and not public.is_superadmin()) then
    raise exception 'Only active admin users can import catalog data';
  end if;

  update public.catalog_import_runs
  set status = 'failed',
      finished_at = now(),
      error_message = nullif(trim(coalesce(message, '')), '')
  where id = run_id
    and organization_id = v_org_id
    and status in ('running', 'validating', 'validated', 'finalizing')
  returning id into v_run_id;

  if v_run_id is null then
    raise exception 'Catalog import run was not found or cannot be failed';
  end if;

  return jsonb_build_object(
    'status', 'failed',
    'run_id', v_run_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_catalog_import_batch_system(input_run_id uuid, input_organization_id uuid, input_actor_id uuid, input_batch_size integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_org uuid;
  v_actor_role text;
begin
  select organization_id, lower(role::text)
    into v_actor_org, v_actor_role
  from public.profiles
  where id = input_actor_id and is_active = true;

  if v_actor_org is null or v_actor_org <> input_organization_id
     or v_actor_role not in ('admin', 'superadmin') then
    raise exception 'System finalization actor is not an active organization admin';
  end if;

  perform set_config('request.jwt.claim.sub', input_actor_id::text, true);
  return public.finalize_catalog_import_batch(input_run_id, input_batch_size);
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_catalog_import_pre_kolbenschmidt(input_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '300s'
AS $function$
declare
  v_org_id uuid;
  v_run public.catalog_import_runs%rowtype;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
  v_error_count integer := 0;
  v_image_quarantined integer := 0;
  v_finalized_by uuid := auth.uid();
begin
  v_org_id := public.current_profile_org_id();

  if v_org_id is null or (public.current_profile_role() <> 'admin' and not public.is_superadmin()) then
    raise exception 'Only active admin users can import catalog data';
  end if;
  if input_run_id is null then
    raise exception 'Catalog import run is required';
  end if;

  select * into v_run
  from public.catalog_import_runs
  where id = input_run_id and organization_id = v_org_id
  for update;

  if not found then raise exception 'Catalog import run was not found'; end if;
  if v_run.status = 'finalized' then raise exception 'Catalog import run has already been finalized'; end if;
  if v_run.status <> 'validated' then raise exception 'Catalog import run cannot be finalized from status %', v_run.status; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_run.organization_id::text || ':' || v_run.id::text || ':catalog_import_finalize', 0));

  begin
    update public.catalog_import_runs set status = 'finalizing', error_message = null where id = v_run.id;

    select count(*)::integer into v_error_count
    from public.catalog_import_stage s
    where s.run_id = v_run.id and s.organization_id = v_org_id and s.validation_status = 'error';
    if v_error_count > 0 then raise exception 'Catalog import run still has validation errors'; end if;

    insert into public.brands (organization_id, name)
    select distinct v_org_id, coalesce(nullif(trim(s.brand), ''), 'Unbranded')
    from public.catalog_import_stage s
    where s.run_id = v_run.id and s.organization_id = v_org_id and nullif(trim(coalesce(s.brand, '')), '') is not null
    on conflict (organization_id, normalized_name) do nothing;

    with ordered_stage_rows as (
      select s.*, b.id as brand_id, cp.id as existing_product_id
      from public.catalog_import_stage s
      left join public.brands b on b.organization_id = v_org_id and public.normalize_catalog_brand_key(b.name) = public.normalize_catalog_brand_key(s.brand)
      left join public.catalog_products cp on cp.organization_id = v_org_id and cp.brand_id = b.id and cp.normalized_code = s.normalized_code
      where s.run_id = v_run.id and s.organization_id = v_org_id and s.validation_status = 'valid' and s.proposed_action in ('insert', 'update', 'skip')
      order by s.row_index asc, s.created_at asc, s.id asc
    ),
    inserted_rows as (
      insert into public.catalog_products (
        organization_id, brand_id, product_code, description, oem_no, hs_code,
        origin, weight_kg, lifecycle_status, lifecycle_note
      )
      select v_org_id, osr.brand_id, osr.product_code,
        nullif(trim(coalesce(osr.description, '')), ''),
        nullif(trim(coalesce(osr.oem_no, '')), ''),
        nullif(trim(coalesce(osr.hs_code, '')), ''),
        nullif(trim(coalesce(osr.origin, '')), ''),
        osr.weight_kg,
        coalesce(nullif(trim(coalesce(osr.lifecycle_status, '')), ''), 'active'),
        nullif(trim(coalesce(osr.lifecycle_note, '')), '')
      from ordered_stage_rows osr
      where osr.proposed_action = 'insert'
      on conflict (organization_id, brand_id, normalized_code) do nothing
      returning 1
    ),
    updated_rows as (
      update public.catalog_products cp
      set description = coalesce(nullif(trim(coalesce(osr.description, '')), ''), cp.description),
          oem_no = coalesce(nullif(trim(coalesce(osr.oem_no, '')), ''), cp.oem_no),
          hs_code = coalesce(nullif(trim(coalesce(osr.hs_code, '')), ''), cp.hs_code),
          origin = coalesce(nullif(trim(coalesce(osr.origin, '')), ''), cp.origin),
          weight_kg = coalesce(osr.weight_kg, cp.weight_kg),
          lifecycle_status = coalesce(nullif(trim(coalesce(osr.lifecycle_status, '')), ''), cp.lifecycle_status),
          lifecycle_note = coalesce(nullif(trim(coalesce(osr.lifecycle_note, '')), ''), cp.lifecycle_note),
          updated_at = now()
      from ordered_stage_rows osr
      where osr.proposed_action = 'update'
        and cp.organization_id = v_org_id and cp.id = osr.existing_product_id
        and cp.brand_id = osr.brand_id and cp.normalized_code = osr.normalized_code
        and (
          cp.description is distinct from coalesce(nullif(trim(coalesce(osr.description, '')), ''), cp.description)
          or cp.oem_no is distinct from coalesce(nullif(trim(coalesce(osr.oem_no, '')), ''), cp.oem_no)
          or cp.hs_code is distinct from coalesce(nullif(trim(coalesce(osr.hs_code, '')), ''), cp.hs_code)
          or cp.origin is distinct from coalesce(nullif(trim(coalesce(osr.origin, '')), ''), cp.origin)
          or cp.weight_kg is distinct from coalesce(osr.weight_kg, cp.weight_kg)
          or cp.lifecycle_status is distinct from coalesce(nullif(trim(coalesce(osr.lifecycle_status, '')), ''), cp.lifecycle_status)
          or cp.lifecycle_note is distinct from coalesce(nullif(trim(coalesce(osr.lifecycle_note, '')), ''), cp.lifecycle_note)
        )
      returning 1
    ),
    skipped_rows as (
      select 1 from ordered_stage_rows osr where osr.proposed_action = 'skip'
    ),
    quarantined_rows as (
      select 1 from ordered_stage_rows osr where nullif(trim(coalesce(osr.image_url, '')), '') is not null
    )
    select
      (select count(*)::integer from inserted_rows),
      (select count(*)::integer from updated_rows),
      (select count(*)::integer from skipped_rows),
      (select count(*)::integer from quarantined_rows)
    into v_inserted, v_updated, v_skipped, v_image_quarantined;

    update public.catalog_import_runs
    set status = 'finalized', finalized_at = now(), finalized_by = coalesce(v_finalized_by, finalized_by, created_by),
        finished_at = now(), error_message = null, inserted_count = v_inserted, updated_count = v_updated,
        skipped_count = v_skipped, image_quarantined_count = v_image_quarantined, error_rows = 0,
        insert_rows = v_inserted, update_rows = v_updated, skip_rows = v_skipped,
        processed_rows = v_inserted + v_updated + v_skipped
    where id = v_run.id;

    return jsonb_build_object(
      'status', 'finalized', 'run_id', v_run.id, 'inserted_count', v_inserted,
      'updated_count', v_updated, 'skipped_count', v_skipped, 'error_count', 0,
      'image_quarantined_count', v_image_quarantined
    );
  exception when others then
    update public.catalog_import_runs set status = 'finalize_failed', finished_at = now(), error_message = sqlerrm where id = v_run.id;
    raise;
  end;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_catalog_provider_stage_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.input_scope ->> 'source' = 'provider_stage_only' then
    if new.status not in ('provider_collecting', 'staged', 'failed', 'cancelled') then
      raise exception 'Provider-stage collections cannot validate, finalize, or apply';
    end if;

    if new.input_scope ->> 'source' is distinct from old.input_scope ->> 'source'
       or new.input_scope ->> 'source_key' is distinct from old.input_scope ->> 'source_key'
       or new.input_scope ->> 'collection_key' is distinct from old.input_scope ->> 'collection_key'
       or new.input_scope ->> 'source_brand' is distinct from old.input_scope ->> 'source_brand'
       or new.input_scope ->> 'brand_name' is distinct from old.input_scope ->> 'brand_name' then
      raise exception 'Provider-stage collection identity is immutable';
    end if;

    if old.status = 'staged' and new.status <> 'staged' then
      raise exception 'A sealed provider-stage collection is immutable';
    end if;
  elsif new.input_scope ->> 'source' = 'provider_stage_only' then
    raise exception 'An existing catalog import cannot be converted into a provider-stage collection';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_product_conflict_integrity_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_organization_id uuid;
  v_product_id uuid;
begin
  if tg_op = 'UPDATE'
     and old.status is not distinct from new.status then
    return new;
  end if;

  if tg_op = 'DELETE' then
    v_organization_id := old.organization_id;
    v_product_id := old.product_id;

    if not exists (
      select 1
      from public.catalog_products cp
      where cp.organization_id = v_organization_id
        and cp.id = v_product_id
    ) then
      return old;
    end if;
  else
    v_organization_id := new.organization_id;
    v_product_id := new.product_id;
  end if;

  perform public.enqueue_catalog_integrity_product(
    v_organization_id,
    v_product_id,
    case
      when tg_op = 'INSERT' then 'conflict_detected'
      when tg_op = 'DELETE' then 'conflict_removed'
      else 'conflict_status_changed'
    end,
    100
  );
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_catalog_operations_brand_summary_after_import()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.status = 'finalized' and old.status is distinct from 'finalized' then
    perform public.refresh_catalog_operations_brand_summary(new.organization_id, null);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_supplier_price_supplier_stats_after_finalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.finalize_phase = 'done'
     and (
       old.finalize_phase is distinct from new.finalize_phase
       or old.finalized_at is distinct from new.finalized_at
       or old.status is distinct from new.status
     ) then
    perform public.refresh_supplier_price_supplier_stats(
      new.organization_id,
      new.supplier_id
    );
    perform public.refresh_supplier_price_supplier_brand_stats(
