CREATE OR REPLACE FUNCTION public.set_supplier_price_deactivated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.deactivated_at := case when new.is_active then null else coalesce(new.deactivated_at, clock_timestamp()) end;
    return new;
  end if;

  if new.is_active and not old.is_active then
    new.deactivated_at := null;
  elsif not new.is_active and (old.is_active or old.deactivated_at is null) then
    new.deactivated_at := coalesce(old.deactivated_at, clock_timestamp());
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.stage_catalog_import_chunk(input_run_id uuid, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
  v_org_id uuid := public.current_profile_org_id();
begin
  v_result := public.stage_catalog_import_chunk_pre_dimensions(input_run_id, payload);

  update public.catalog_import_stage s
  set dimensions = case
    when jsonb_typeof(p.dimensions) in ('object', 'array') then p.dimensions
    else null
  end
  from (
    select
      case
        when nullif(trim(coalesce(item.value->>'row_index', '')), '') ~ '^[0-9]+$'
          then (item.value->>'row_index')::integer
        else null
      end as row_index,
      item.value->'dimensions' as dimensions
    from jsonb_array_elements(coalesce(payload, '[]'::jsonb)) with ordinality as item(value, ordinality)
  ) p
  where s.run_id = input_run_id
    and s.organization_id = v_org_id
    and p.row_index = s.row_index;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.stage_catalog_import_chunk_pre_dimensions(input_run_id uuid, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
  v_org_id uuid := public.current_profile_org_id();
begin
  v_result := public.stage_catalog_import_chunk_pre_description_tr(input_run_id, payload);

  update public.catalog_import_stage s
  set description_tr = p.description_tr
  from (
    select
      nullif(trim(coalesce(item.value->>'row_index', '')), '')::integer as row_index,
      nullif(trim(coalesce(
        item.value->>'description_tr',
        item.value->>'description_turkish',
        item.value->>'Product_Name_TR',
        ''
      )), '') as description_tr
    from jsonb_array_elements(coalesce(payload, '[]'::jsonb)) as item(value)
  ) p
  where s.run_id = input_run_id
    and s.organization_id = v_org_id
    and s.row_index = p.row_index;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_invoice_stock_movements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    perform public.reverse_invoice_stock_movements_for_org(
      old.organization_id,
      old.id,
      'Invoice deleted; reversing posted stock movements'
    );
    return old;
  end if;

  if lower(coalesce(new.status, 'draft')) in ('draft', 'void') then
    perform public.reverse_invoice_stock_movements_for_org(
      new.organization_id,
      new.id,
      'Invoice is no longer stock-active; reversing posted stock movements'
    );
    return new;
  end if;

  perform public.post_invoice_stock_movements_for_org(
    new.organization_id,
    new.id,
    'Invoice stock movement synchronization'
  );

  return new;
end;
$function$

